 cx_kMark:d=>{const k=ui.cx_k,r=get('relaciones',k.rel),ti=tiApi();if(!r||!k.ok||!ti)return;const er=ti.marcar(r,d.t,'Kiosko',{det:(k.modo==='doc'?'Documento y PIN verificados':'PIN verificado')+' · kiosko de sede'});if(er){k.err=er;toast(er);return render()}
  const md=k.modo;ui.cx_k=K0();ui.cx_k.modo=md;ui.cx_k.done={t:ti.ML[d.t]+' registrada',n:nm(r),h:hmNow()};save();render();clearTimeout(KT);KT=setTimeout(()=>{if(ui.full==='cx_kiosko'&&ui.cx_k&&ui.cx_k.done){kReset(1);render()}},(+param('kiosko.cierreSeg')||8)*1000)},
