const perFin=pp=>pp+'-'+String(new Date(+pp.slice(0,4),+pp.slice(5,7),0).getDate()).padStart(2,'0');
const socio=()=>{const ap=plApi();return ap&&session&&session.socio?ap.PL().socios.find(s=>s.id===session.socio&&s.activo)||null:null};
function withT(tid,uid,fn){const prev=session;session={tenantId:tid,userId:uid,socio:prev&&prev.socio};try{return fn()}finally{session=prev}}
function estInfo(s,tid){const te=db.tenants.find(t=>t.id===tid),d=db.data[tid];if(!te||!d)return null;syncSocios(d,tid);const x=d.cx_terceros.find(y=>y.socioId===s.id),acc=te.estado!=='Activa'?'Organización suspendida':!x?'Sin acceso':terEst(x),ok=acc==='Vigente';
 const nomOn=(!te.modulos||te.modulos.includes('nomina'))&&Array.isArray(d.nomPeriodos),emps=d.empresas.filter(e=>e.activo!==false&&e.pais==='Perú'),fin=perFin(CURP);
 const pl_=emps.map(e=>({e,p:nomOn?d.nomPeriodos.find(p=>p.empresaId===e.id&&p.periodo===CURP):null,n:d.relaciones.filter(r=>r.empresaId===e.id&&r.ingreso<=fin&&(!r.cese||r.cese>=CURP+'-01')).length}));
 const pend=[];if(nomOn){const sin=pl_.filter(x=>!x.p&&x.n).length;if(sin)pend.push(pl(sin,'empresa')+' sin periodo de '+MESN[+CURP.slice(5,7)-1]);const cal=d.nomPeriodos.filter(p=>p.estado==='Calculado').length;if(cal)pend.push(pl(cal,'planilla')+' por aprobar');const tr=(d.nomTreg||[]).filter(r=>r.estado==='Pendiente').length;if(tr)pend.push(pl(tr,'movimiento')+' de T-Registro por declarar')}
 const cv=d.relaciones.filter(r=>r.estado==='Activo'&&r.contratoFin&&days(TODAY,r.contratoFin)<=30).length;if(cv)pend.push(pl(cv,'contrato')+' por vencer en 30 días');
 return{te,d,x,acc,ok,nomOn,pl:pl_,pend,act:d.relaciones.filter(r=>r.estado==='Activo').length}}
