 actions:ACT,init,hooks:HOOKS,alerts:alertas,
 topbar,sideFoot:()=>[['cx_cuenta','Mi cuenta','user'],...(allowed('pl_cfg')?[['cx_cfg','Configuración','settings']]:[])],userMenu:()=>[['cx_cuenta','Mi cuenta'],['cx_cuentaNotif','Notificaciones'],...(session.socio?[['cx_eVolver','Volver a la cartera del estudio']]:[])],
 loginExtra,loginCheck,
 colabBulk:{can:()=>can('colaborador.masivo')&&can('colaborador.editar'),bar:bulkBar},
